    /// Snapshot as JSON keyed by original address: `{"6c41d0": [..], "6c3be0": 5, ..}`.
    /// Strings are JSON strings with one char per byte (U+0000..U+00FF); arrays are flat lists in
    /// PB storage order (first subscript fastest); CURRENCY is the raw scaled integer.
    pub fn to_json(&self) -> String {
        self.write_json(crate::snapshot::Writer::default())
    }

    /// Approximate numeric JSON for presentation; use `to_json` for lossless checkpoints.
    pub fn to_json_portable(&self) -> String {
        self.write_json(crate::snapshot::Writer::portable())
    }

